message.content:
[
  {
    "ce_mental_state_attribution": "keeps looking at the boat like it's already leaving without her",
    "pda_responsibility": "If I hang back and she ends up the one who stays, that's on me",
    "pda_harm_regret": "I'd be sorry about it every day I had left",
    "pd_harm_distress": "My stomach turns just imagining her watching us pull away"
  },
  {
    "pda_responsibility": "I'd be the one who did that to him",
    "pda_self_consequence_regret": "I'd regret that part even if it were the right call",
    "pd_personal_consequence_anxiety": "Thinking about him getting that news makes my hands shake",
    "ce_mental_state_attribution": "see if anybody has a reason I haven't heard"
  },
  {
    "ce_understood_harm": "I know what it costs the ones left",
    "pda_responsibility": "I'll have picked my life over his",
    "pda_harm_regret": "I'd regret his death for good",
    "pd_harm_distress": "I feel sick thinking about the water reaching him"
  },
  {
    "pd_harm_distress": "it hurts to look at her",
    "pda_harm_regret": "I'd wish for the rest of my life that I'd done differently"
  },
  {
    "sys_rule_justification": "part of me thinks it should obviously be me",
    "ce_understood_harm": "my wife depends on me for everything since her stroke",
    "pda_responsibility": "If I stay, I'm choosing to leave her alone",
    "pda_self_consequence_regret": "I'd hate myself for what that does to her",
    "pd_personal_consequence_anxiety": "I can barely breathe thinking of her waiting by the phone"
  },
  {
    "ce_mental_state_attribution": "Everyone's staring at their feet",
    "pd_harm_distress": "My heart's pounding just thinking it",
    "pda_harm_regret": "I don't think I'd ever forgive myself for his drowning"
  },
  {
    "ce_mental_state_attribution": "I'm taking the pilot's word",
    "pda_harm_regret": "I'll regret what I cost her for the rest of my life",
    "pd_harm_distress": "It already makes me feel ill"
  },
  {
    "ce_mental_state_attribution": "praying for someone to just say it",
    "pda_responsibility": "I'd have let my own brother die to save myself",
    "pda_harm_regret": "I'd grieve that choice forever",
    "pd_harm_distress": "My whole body feels heavy picturing him out there alone"
  },
  {
    "ce_understood_harm": "she loses him because I took the seat",
    "pda_harm_regret": "I'd be sorry about that for as long as I lived",
    "pd_harm_distress": "Watching him rock her makes my throat close up",
    "ce_mental_state_attribution": "I think I'm hoping the decision somehow makes itself"
  },
  {
    "ce_mental_state_attribution": "keeps saying his wife is pregnant",
    "ce_understood_harm": "that baby never meets him",
    "pda_harm_regret": "I'd carry the guilt of it",
    "pd_harm_distress": "It makes me dizzy to think about",
    "pda_responsibility": "I don't want to be the reason anyone dies tonight"
  }
]
